// 一次性生成器: 从当前产物反推「默认模板三段文本」。
//
// 做法: 取当前产物（3 条消息），把动态值/条件段挖成 `{{彼方:名}}` 洞。
//   挖完的文本 = 默认模板。
// 验证: 用**另一组数据**渲染这个模板，必须与那一组数据的产物逐字节相同。
//   （用同一组数据验是循环论证：挖洞时用的就是它。）
//
// 输出: tests/fixtures/生成-默认模板.json（三段文本 + 占位符清单）
import { writeFileSync } from 'node:fs';
import { buildTest } from '../build.mjs';
import path from 'node:path';

const 入口 = path.join(import.meta.dirname, '_gen-tpl.ts');
const 产物 = path.join(import.meta.dirname, '_gen-tpl.mjs');

const 源码 = [
  "import { buildUpdateMessages } from '../../src/彼方_NPC幕后生命状态系统/prompts';",
  "",
  "// ── 样本 A: 挖洞用 ──",
  "// ⚠ replyCount 必须用**独一无二的数字**: 第一版用了 3, 结果把正文里「见原则 3」的 3",
  "//   也替换掉了, 模板里出现「见原则 7」—— 挖洞污染。所以用 987654（正文里不会自然出现）。",
  "const 甲 = {",
  "  reply: 'AAAREPLY', replyCount: 987654, context: 'AAACTX', timeJump: 'AAAJUMP',",
  "  tracked: ['AAATRK1', 'AAATRK2'], inSceneHint: ['AAAHINT'],",
  "  currentCards: { AAACARD: { 当前在做: 'x' } },",
  "  worldbook: 'AAAWB', currentStoryTime: 'AAACTIME',",
  "  storyTimeHint: 'AAASTIME', storySpan: 'AAASPAN', recentTrace: 'AAATRACE',",
  "  playerName: 'AAAPNAME', playerDescription: 'AAAPDESC',",
  "};",
  "// ── 样本 B: 验证用（值完全不同，且不含 A 的标记）──",
  "const 乙 = {",
  "  reply: 'BBBREPLY', replyCount: 246813, context: 'BBBCTX', timeJump: 'BBBJUMP',",
  "  tracked: ['BBBT1'], inSceneHint: ['BBBH1', 'BBBH2'],",
  "  currentCards: { BBBCARD: { 当前在做: 'y' } },",
  "  worldbook: 'BBBWB', currentStoryTime: 'BBBCTIME',",
  "  storyTimeHint: 'BBBSTIME', storySpan: 'BBBSPAN', recentTrace: 'BBBTTRACE',",
  "  playerName: 'BBBPNAME', playerDescription: 'BBBDESC',",
  "};",
  "",
  "const 造 = (标, 额外 = {}) => ({",
  "  autoTrackEnabled: true, physioEnabled: false, 恋爱对象名单: [],",
  "  预填充: false, 展开宏: (t) => t, ...标, ...额外,",
  "});",
  "",
  "const 跑 = (标, 额外) => {",
  "  const 原I = console.info, 原T = console.table, 原W = console.warn;",
  "  console.info = () => {}; console.table = () => {}; console.warn = () => {};",
  "  let r;",
  "  try { r = buildUpdateMessages(造(标, 额外)); }",
  "  finally { console.info = 原I; console.table = 原T; console.warn = 原W; }",
  "  return r;",
  "};",
  "",
  "// 值 → 占位符名。顺序很重要: 长值优先（避免短值吃掉长值的一部分）",
  "const 值名 = (标) => [",
  "  ['最近正文', 标.reply],",
  "  ['正文条数', String(标.replyCount)],",
  "  ['世界书', 标.worldbook],",
  "  ['正文时间', 标.storyTimeHint],",
  "  ['时间跳跃', 标.timeJump],",
  "  ['上次剧情时间', 标.currentStoryTime],",
  "  ['剧情跨度', 标.storySpan],",
  "  ['追踪名单', 标.tracked.join('、')],",
  "  ['正文提到的人', 标.inSceneHint.join('、')],",
  "  ['主角名', 标.playerName],",
  "  ['主角描述', 标.playerDescription],",
  "  ['近期轨迹', 标.recentTrace],",
  "  ['场景判断输入', 标.context],",
  "];",
  "",
  "function 挖(文本, 标) {",
  "  let 文 = 文本;",
  "  const 表 = 值名(标).filter(([, v]) => v && String(v).length > 0);",
  "  // 长值优先",
  "  表.sort((a, b) => String(b[1]).length - String(a[1]).length);",
  "  for (const [名, v] of 表) 文 = 文.split(String(v)).join('{{彼方:' + 名 + '}}');",
  "  return 文;",
  "}",
  "",
  "const A = 跑(甲);",
  "const B = 跑(乙);",
  "",
  "console.log('=== 当前产物结构（样本 A）===');",
  "A.messages.forEach((m, i) => console.log('  第' + (i+1) + '条', m.role, 'len=' + String(m.content).length));",
  "",
  "// 三段 = 三条消息（默认模式）",
  "const 段名 = ['系统段', '场景判断', '用户段'];",
  "const 模板 = {};",
  "A.messages.forEach((m, i) => { 模板[段名[i]] = 挖(String(m.content), 甲); });",
  "",
  "console.log('');",
  "console.log('=== 挖洞后各段 ===');",
  "for (const [名, 文] of Object.entries(模板)) {",
  "  const 洞 = (文.match(/\\{\\{彼方:/g) || []).length;",
  "  console.log(名, 'len=' + 文.length, '洞=' + 洞);",
  "}",
  "",
  "// ── 验证: 用样本 B 渲染, 必须 === B 的产物 ──",
  "function 渲染(文本, 标, 内容表) {",
  "  return 文本.replace(/\\{\\{彼方:([^}]+)\\}\\}/g, (_, 名) => {",
  "    const v = 内容表[名];",
  "    return v === undefined ? '\\u0000缺' + 名 + '\\u0000' : String(v);",
  "  });",
  "}",
  "const B值表 = Object.fromEntries(值名(乙).map(([名, v]) => [名, v]));",
  "",
  "console.log('');",
  "console.log('=== 用样本 B 渲染，与 B 的产物比对 ===');",
  "let 全对 = true;",
  "B.messages.forEach((m, i) => {",
  "  const 出 = 渲染(模板[段名[i]], 乙, B值表);",
  "  const 原 = String(m.content);",
  "  const 同 = 出 === 原;",
  "  if (!同) 全对 = false;",
  "  console.log('第' + (i+1) + '条', 同 ? '✓ 逐字节相同' : '✗ 不同');",
  "  if (!同) {",
  "    for (let k = 0; k < Math.max(出.length, 原.length); k++) {",
  "      if (出[k] !== 原[k]) {",
  "        console.log('   首个差异 @', k);",
  "        console.log('   模板渲染:', JSON.stringify(出.slice(Math.max(0,k-50), k+50)));",
  "        console.log('   实际产物:', JSON.stringify(原.slice(Math.max(0,k-50), k+50)));",
  "        break;",
  "      }",
  "    }",
  "  }",
  "});",
  "console.log('全部相同?', 全对);",
  "",
  "// ── 也验一下条件段为空时的行为（世界书空 / 场景判断空）──",
  "console.log('');",
  "console.log('=== 条件为空时的洞（这些洞必须能整块消失）===');",
  "const 空 = 跑({ ...甲, worldbook: '', context: '', recentTrace: '' });",
  "空.messages.forEach((m, i) => {",
  "  const c = String(m.content);",
  "  console.log('  第' + (i+1) + '条 len=' + c.length);",
  "});",
  "console.log('  → 空世界书时 D2 整段消失；模板里那一行必须跟着消失');",
  "",
  "writeFileSync('tests/fixtures/生成-默认模板.json', JSON.stringify({ 模板, 全对 }, null, 2));",
  "console.log('');",
  "console.log('已写出 tests/fixtures/生成-默认模板.json');",
].join('\n');

writeFileSync(入口, 源码);

await buildTest(入口, 产物);
await import(new URL(`file:///${产物.replace(/\\/g, '/')}`).href);
